# ---------------------------------------------------------------------------
# 密碼保護
# ---------------------------------------------------------------------------
def check_password() -> bool:
    def _password_entered():
        correct = st.secrets.get("APP_PASSWORD", None)
        if correct is None:
            st.session_state["password_ok"] = True  # 沒設密碼時，本機測試放行
            return
        st.session_state["password_ok"] = (
            st.session_state.get("password_input", "") == correct
        )

    if st.session_state.get("password_ok"):
        return True

    st.title("零件耗用 / 故障率查詢")
    st.text_input("請輸入密碼", type="password", key="password_input",
                   on_change=_password_entered)
    if st.session_state.get("password_ok") is False:
        st.error("密碼錯誤，請再試一次")
    return False


# ---------------------------------------------------------------------------
# 資料讀取與清理
# ---------------------------------------------------------------------------
def read_excel(uploaded_file) -> pd.DataFrame:
    return pd.read_excel(uploaded_file)


def read_any_excel(file_bytes: bytes) -> pd.DataFrame:
    """同時支援 .xlsx（openpyxl）與舊版 .xls（xlrd）。"""
    return pd.read_excel(io.BytesIO(file_bytes))


def validate_columns(df: pd.DataFrame, required: list, label: str) -> list:
    missing = [c for c in required if c not in df.columns]
    if missing:
        st.error(
            f"「{label}」缺少欄位：{missing}。目前偵測到的欄位是：{list(df.columns)}。"
            f"請確認檔案格式，或告訴我正確欄位名稱讓我調整程式。"
        )
    return missing


def branch_from_repair_no(repair_no: str) -> str:
    if not isinstance(repair_no, str) or len(repair_no) < 5:
        return "未知"
    code = repair_no[4]  # 第5碼，index 4
    return BRANCH_CODE_MAP.get(code.upper(), "未知")


def extract_year_month(d) -> str:
    """回傳 'YYYY-MM'；輸入可能已經是 datetime，也可能是文字。"""
    if pd.isna(d):
        return None
    if isinstance(d, (pd.Timestamp, datetime, date)):
        return f"{d.year:04d}-{d.month:02d}"
    s = str(d)
    m = re.match(r"(\d{4})[-/](\d{1,2})", s)
    if m:
        return f"{int(m.group(1)):04d}-{int(m.group(2)):02d}"
    return None


def classify_part(code: str, name: str):
    """四層判定故障部位分類，回傳 (分類, 判定方式)：
    0. 人工修正清單（NAME_OVERRIDES）優先權最高
    1. 零件編號精確比對內嵌分類表
    2. 品名精確比對
    3. 品名包含某個分類名稱（關鍵字比對）
    4. 都對不到 -> 歸類「其他」，判定方式標「無法判別」讓使用者可以抽查"""
    code = str(code)
    name = str(name) if pd.notna(name) else ""
    if name in NAME_OVERRIDES:
        return NAME_OVERRIDES[name], "人工修正"
    if code in CODE_TO_CATEGORY:
        return CODE_TO_CATEGORY[code], "零件編號精確比對"
    if name in NAME_TO_CATEGORY:
        return NAME_TO_CATEGORY[name], "品名精確比對"
    for cat in KNOWN_CATEGORIES:
        if cat and cat in name:
            return cat, "關鍵字比對"
    return "其他", "無法判別"


@st.cache_data(show_spinner=False)
def build_usage_df(usage_files_bytes: list):
    """usage_files_bytes：一個或多個零件耗用資料檔案（bytes 的 list），
    直接全部合併，不需要去重（同一張維修單合法地用到同一個零件兩次的情況
    是存在的，用維修單號+零件編號去重會誤刪真實資料）。
    機型分類、故障部位分類都改用內嵌對照表，不再需要另外上傳檔案。"""
    dfs = []
    for i, b in enumerate(usage_files_bytes, start=1):
        df = read_any_excel(b)
        validate_columns(df, list(ASSUMED_USAGE_COLUMNS.values()), f"零件耗用資料（第{i}個檔案）")
        dfs.append(df)
    usage = pd.concat(dfs, ignore_index=True)

    model_map = pd.DataFrame(MODEL_RECORDS)  # 欄位: 機型/類別/內外機

    cols = ASSUMED_USAGE_COLUMNS

    # 排除零件編號空白、數量為0的列（不是真的耗用，是同一張維修單的參考列）
    usage = usage[usage[cols["part_no"]].notna() & (usage[cols["qty"]] > 0)].copy()

    usage["年月"] = usage[cols["fault_date"]].apply(extract_year_month)
    usage["維修分公司"] = usage[cols["repair_no"]].apply(branch_from_repair_no)
    usage["有無償"] = usage[cols["payment_type"]]

    # 關聯機型分類表 -> 類別 / 內外機
    model_lookup = model_map.set_index("機型")[["類別", "內外機"]]
    usage = usage.join(model_lookup, on=cols["model"])
    usage = usage.rename(columns={cols["model"]: "機型"})

    # ⚠️ 2026/08 重要修正：以前這裡如果機型分類表沒有這個機型（join失敗，
    # 類別/內外機變成 NaN），後面 groupby 會直接把這些列「整組排除」，
    # 數字悄悄變少但畫面上完全看不出來。改成用「未分類機型」頂著，這樣
    # 這些機型還是會出現在結果裡（歸在「未分類機型」類別下），不會憑空消失，
    # 同時上面也會跳警告列出哪些機型沒有分類資料。
    unmatched_models = sorted(
        usage.loc[usage["類別"].isna(), "機型"].dropna().unique().tolist()
    )
    usage["類別"] = usage["類別"].fillna("未分類機型")
    usage["內外機"] = usage["內外機"].fillna("未分類機型")

    # 故障部位：四層判定（人工修正 -> 零件編號 -> 品名精確 -> 品名關鍵字 -> 其他）
    classified = usage.apply(
        lambda r: classify_part(r[cols["part_no"]], r[cols["part_name"]]),
        axis=1, result_type="expand",
    )
    usage["故障部位"] = classified[0]
    usage["判定方式"] = classified[1]
    usage = usage.rename(columns={cols["part_no"]: "零件料號"})
    usage["零件料號"] = usage["零件料號"].astype(str)

    # 分類判定結果稽核清單（給使用者抽查用，尤其是「無法判別」的）
    audit = (
        usage[["零件料號", cols["part_name"], "故障部位", "判定方式"]]
        .drop_duplicates()
        .rename(columns={cols["part_name"]: "品名"})
        .sort_values(["判定方式", "零件料號"])
        .reset_index(drop=True)
    )

    return usage, audit, model_map, unmatched_models


@st.cache_data(show_spinner=False)
def build_shipment_df(shipment_bytes):
    xl = pd.ExcelFile(io.BytesIO(shipment_bytes))
    chosen = None
    for name in xl.sheet_names:
        tmp = xl.parse(name, nrows=3)
        if SHIPMENT_MODEL_COL in tmp.columns and any(
            SHIPMENT_YEAR_COL_PATTERN.match(str(c)) for c in tmp.columns
        ):
            chosen = name
            break
    if chosen is None:
        chosen = xl.sheet_names[0]
    df = xl.parse(chosen)
    validate_columns(df, [SHIPMENT_MODEL_COL], "出貨資料")
    year_cols = [c for c in df.columns if SHIPMENT_YEAR_COL_PATTERN.match(str(c))]
    if not year_cols:
        st.warning("在出貨資料裡找不到「20XX販售量」這種格式的欄位，累積出貨量會算不出來，"
                   "請確認出貨資料的欄位名稱。")
    return df, year_cols


# ---------------------------------------------------------------------------
# 業務邏輯：零件耗用一覽
# ---------------------------------------------------------------------------
def shift_month(ym: str, months: int) -> str:
    y, m = map(int, ym.split("-"))
    idx = y * 12 + (m - 1) + months
    return f"{idx // 12:04d}-{idx % 12 + 1:02d}"


def _apply_filter(scope, col, selected):
    """selected 是 multiselect 回傳的 list；空 list 代表不篩選（=全部）。"""
    if selected:
        scope = scope[scope[col].isin(selected)]
    return scope


def usage_table(usage_df, start_ym, end_ym, f_cat, f_io, f_model, f_part, f_partno, f_branch, f_payment):
    """查找年月(起始~結束) 整段期間內的耗用量加總。
    2026/08 更新：類別/機型/故障部位/零件料號/維修分公司/有無償 都改成多選
    （list，空 list = 不篩選），加了「當期耗用金額」欄位，最後加一列總計。"""
    scope = usage_df[(usage_df["年月"] >= start_ym) & (usage_df["年月"] <= end_ym)]
    scope = _apply_filter(scope, "類別", f_cat)
    if f_io != "全部": scope = scope[scope["內外機"] == f_io]
    scope = _apply_filter(scope, "機型", f_model)
    scope = _apply_filter(scope, "故障部位", f_part)
    scope = _apply_filter(scope, "零件料號", f_partno)
    scope = _apply_filter(scope, "維修分公司", f_branch)
    scope = _apply_filter(scope, "有無償", f_payment)

    group_cols = ["類別", "內外機", "機型", "故障部位", "零件料號", "維修分公司"]
    qty_col = ASSUMED_USAGE_COLUMNS["qty"]
    amt_col = ASSUMED_USAGE_COLUMNS["subtotal"]
    result = (
        scope.groupby(group_cols, as_index=False)[[qty_col, amt_col]]
        .sum()
        .rename(columns={"內外機": "室內/外機", qty_col: "當期耗用量", amt_col: "當期耗用金額"})
    )
    result = result[USAGE_TABLE_COLS]

    if len(result) > 0:
        total_row = {c: "" for c in USAGE_TABLE_COLS}
        total_row["類別"] = "總計"
        total_row["當期耗用量"] = result["當期耗用量"].sum()
        total_row["當期耗用金額"] = result["當期耗用金額"].sum()
        result = pd.concat([result, pd.DataFrame([total_row])], ignore_index=True)

    return result, scope


# ---------------------------------------------------------------------------
# 業務邏輯：故障率
# ---------------------------------------------------------------------------
def cumulative_shipment(shipment_df, year_cols, model, end_ym):
    """<最早年度>/01/01 ~ end_ym 月底 的累積出貨量（受限於出貨資料是年度粒度）"""
    end_year = int(end_ym.split("-")[0])
    row = shipment_df[shipment_df[SHIPMENT_MODEL_COL] == model]
    if row.empty:
        return 0
    total = 0
    for c in year_cols:
        y = int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1))
        if y <= end_year:
            total += row[c].sum()
    return total


def earliest_shipment_year(year_cols) -> int:
    years = [int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1)) for c in year_cols]
    return min(years) if years else None


def earliest_nonzero_year_for_model(shipment_df, year_cols, model) -> int:
    """2026/08 新增：不是抓檔案裡最早的年度欄位，而是抓「這個機型」出貨量
    第一次不為 0 的那一年（例如檔案從2010年開始有欄位，但這台機型是2016年
    才開始賣，就回傳2016）。找不到機型或全部是0，退回檔案最早年度。"""
    row = shipment_df[shipment_df[SHIPMENT_MODEL_COL] == model]
    if row.empty:
        return earliest_shipment_year(year_cols)
    years_sorted = sorted(
        (int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1)), c) for c in year_cols
    )
    for y, c in years_sorted:
        if row[c].sum() > 0:
            return y
    return earliest_shipment_year(year_cols)


def build_year_options(shipment_df, year_cols, usage_df):
    """2026/08 新增：歷年累積故障率的「查找年月」改成年度下拉選單，不能選
    月/日。過去年度顯示「YYYY」，代表算到該年12月底；今年這種還沒過完的
    年度，顯示「YYYY/MM」（MM=今天往前推一個月，也就是最後一個完整月），
    以後每年會依系統當天日期自動這樣算，不用每年手動改。
    回傳 [(顯示文字, 對應的end_ym), ...]，由舊到新排序。"""
    years = {int(SHIPMENT_YEAR_COL_PATTERN.match(c).group(1)) for c in year_cols}
    usage_years = {int(ym.split("-")[0]) for ym in usage_df["年月"].dropna()}
    all_years = sorted(years | usage_years)
    if not all_years:
        return []

    today = datetime.now()
    current_year = today.year
    options = []
    for y in all_years:
        if y > current_year:
            continue
        if y == current_year:
            if today.month == 1:
                continue  # 今年還沒有任何一個完整月份，先不提供這個選項
            last_complete_month = today.month - 1
            options.append((f"{y}/{last_complete_month:02d}", f"{y}-{last_complete_month:02d}"))
        else:
            options.append((str(y), f"{y}-12"))
    return options


def _filter_scope(usage_df, f_cat, f_io, f_model, f_part, f_partno, f_branch):
    scope = usage_df
    scope = _apply_filter(scope, "類別", f_cat)
    if f_io != "全部": scope = scope[scope["內外機"] == f_io]
    scope = _apply_filter(scope, "機型", f_model)
    scope = _apply_filter(scope, "故障部位", f_part)
    scope = _apply_filter(scope, "零件料號", f_partno)
    scope = _apply_filter(scope, "維修分公司", f_branch)
    return scope


def rate_table(usage_df, shipment_df, year_cols, end_ym,
                f_cat, f_io, f_model, f_part, f_partno, f_branch):
    """2026/08 大改：
    - 類別/機型/故障部位/零件料號/維修分公司 都改成多選（零件料號不再鎖定）
    - 新增「去年累積故障率」「前年累積故障率」兩欄（同一組合，基準年往前推
      1年/2年，一律算到該年12月底）
    - 總計列的故障率也真的算（用所有組合的累積故障數量加總 ÷ 各機型累積
      出貨量加總，每個機型只算一次，不會因為同機型有多列而重複計算出貨量）
    - 回傳 (result_df, red_flags)：red_flags 是跟 result_df 同樣長度的
      bool list，True 代表「該月故障率」比「去年累積故障率」成長超過3成，
      畫面上要整列反紅
    算法：累積耗用數量 ÷ 累積出貨量，都是（該機型最早非0年度）/01/01 ~
    基準月底。當選了多個機型時，各自機型用各自的最早年度計算，互不影響。"""
    scope = _filter_scope(usage_df, f_cat, f_io, f_model, f_part, f_partno, f_branch)
    group_cols = ["類別", "內外機", "機型", "故障部位", "零件料號", "維修分公司"]
    combos = scope[group_cols].drop_duplicates()

    if combos.empty:
        return pd.DataFrame(columns=RATE_TABLE_COLS), []

    end_year = int(end_ym.split("-")[0])
    last_year_end = f"{end_year - 1}-12"
    two_years_ago_end = f"{end_year - 2}-12"

    def cumulative_qty_by_combo(target_ym):
        sub = scope[scope["年月"] <= target_ym]
        if sub.empty:
            return pd.Series(dtype=float)
        return sub.groupby(group_cols)[ASSUMED_USAGE_COLUMNS["qty"]].sum()

    cum_end = cumulative_qty_by_combo(end_ym)
    cum_last_year = cumulative_qty_by_combo(last_year_end)
    cum_two_years_ago = cumulative_qty_by_combo(two_years_ago_end)

    combos = combos.set_index(group_cols)
    combos["累積故障數量"] = cum_end.reindex(combos.index).fillna(0)
    combos["_qty_last_year"] = cum_last_year.reindex(combos.index).fillna(0)
    combos["_qty_two_years_ago"] = cum_two_years_ago.reindex(combos.index).fillna(0)
    combos = combos.reset_index()

    unique_models = combos["機型"].unique().tolist()
    ship_end = {m: cumulative_shipment(shipment_df, year_cols, m, end_ym) for m in unique_models}
    ship_last_year = {m: cumulative_shipment(shipment_df, year_cols, m, last_year_end) for m in unique_models}
    ship_two_years_ago = {m: cumulative_shipment(shipment_df, year_cols, m, two_years_ago_end) for m in unique_models}

    def safe_rate(qty, ship):
        return (qty / ship) if ship else None

    combos["_rate_end"] = combos.apply(lambda r: safe_rate(r["累積故障數量"], ship_end[r["機型"]]), axis=1)
    combos["_rate_last_year"] = combos.apply(
        lambda r: safe_rate(r["_qty_last_year"], ship_last_year[r["機型"]]), axis=1
    )
    combos["_rate_two_years_ago"] = combos.apply(
        lambda r: safe_rate(r["_qty_two_years_ago"], ship_two_years_ago[r["機型"]]), axis=1
    )

    # 異常反紅：該月故障率比去年累積故障率成長超過3成
    def is_anomaly(row):
        cur, prev = row["_rate_end"], row["_rate_last_year"]
        if pd.isna(cur) or pd.isna(prev) or prev <= 0:
            return False
        return (cur - prev) / prev > 0.3

    red_flags = combos.apply(is_anomaly, axis=1).tolist()

    combos = combos.rename(columns={
        "內外機": "室內/外機",
        "_rate_end": "該月/該料號累積故障率",
        "_rate_last_year": "去年累積故障率",
        "_rate_two_years_ago": "前年累積故障率",
    })
    for c in ["該月/該料號累積故障率", "去年累積故障率", "前年累積故障率"]:
        combos[c] = combos[c].apply(lambda v: f"{v:.2%}" if pd.notna(v) else "-")
    result = combos[RATE_TABLE_COLS]

    if len(result) > 0:
        total_qty = result["累積故障數量"].sum()
        total_ship_end = sum(ship_end[m] for m in unique_models)
        total_ship_last_year = sum(ship_last_year[m] for m in unique_models)
        total_ship_two_years_ago = sum(ship_two_years_ago[m] for m in unique_models)
        total_row = {c: "" for c in RATE_TABLE_COLS}
        total_row["類別"] = "總計"
        total_row["累積故障數量"] = total_qty
        total_row["該月/該料號累積故障率"] = (
            f"{total_qty/total_ship_end:.2%}" if total_ship_end else "-"
        )
        total_qty_last_year = combos["_qty_last_year"].sum()
        total_row["去年累積故障率"] = (
            f"{total_qty_last_year/total_ship_last_year:.2%}" if total_ship_last_year else "-"
        )
        total_row["前年累積故障率"] = (
            f"{combos['_qty_two_years_ago'].sum()/total_ship_two_years_ago:.2%}" if total_ship_two_years_ago else "-"
        )
        result = pd.concat([result, pd.DataFrame([total_row])], ignore_index=True)
        red_flags = red_flags + [False]  # 總計列不參與反紅判斷

    return result, red_flags


